// Pseudocode sketch for a two-pass detector
function detect(text){
  const onDeviceProb = lightweightModel.predict(text);
  if(onDeviceProb > 0.8) return {flag: true, method:'on-device'};
  const cloudFeat = extractProvenanceFeatures(text);
